package com.bank.gitops;

import java.util.ArrayDeque;
import java.util.Deque;

// Git is the single source of truth: it holds the desired image tag + history.
public class GitRepo {
    private final Deque<String> history = new ArrayDeque<>();

    public GitRepo(String initialTag) {
        history.push(initialTag);
    }

    // A deploy is a commit changing the desired image tag.
    public void commit(String newTag) {
        history.push(newTag);
    }

    // git revert: go back to the previous declared state.
    public void revert() {
        if (history.size() > 1) history.pop();
    }

    public String desiredTag() {
        return history.peek();
    }
}
