package com.bank.gitops;

// The live cluster: it holds whatever is actually running right now.
public class Cluster {
    private String liveTag;

    public Cluster(String liveTag) { this.liveTag = liveTag; }

    public String getLiveTag() { return liveTag; }

    // apply: the controller sets the live state to match Git.
    public void apply(String tag) { this.liveTag = tag; }

    // Simulates an out-of-band manual kubectl change (drift).
    public void manualOverride(String tag) { this.liveTag = tag; }
}
