package com.bank.gitops;

import java.util.logging.Logger;

// Pull-based reconciler (ArgoCD/Flux): makes the cluster match Git.
public class GitOpsController {
    private static final Logger log = Logger.getLogger(GitOpsController.class.getName());
    private final GitRepo git;
    private final Cluster cluster;
    private final boolean selfHeal;

    public GitOpsController(GitRepo git, Cluster cluster, boolean selfHeal) {
        this.git = git;
        this.cluster = cluster;
        this.selfHeal = selfHeal;
    }

    // One reconciliation pass: compare desired vs live, converge if needed.
    public void reconcile() {
        String desired = git.desiredTag();
        String live = cluster.getLiveTag();
        if (desired.equals(live)) {
            log.info(() -> "SYNCED: live=" + live + " matches Git");
            return;
        }
        if (selfHeal) {
            log.warning(() -> "OUT_OF_SYNC: live=" + live + " desired=" + desired + " -> healing");
            cluster.apply(desired);
            log.info(() -> "RECONCILED: cluster now runs " + desired);
        } else {
            log.warning(() -> "OUT_OF_SYNC: live=" + live + " desired=" + desired + " (manual sync required)");
        }
    }
}
