package com.bank.gitops;

import java.util.logging.Logger;

// Old push style: an external pipeline pushes directly into the cluster.
public class PushDeployer {
    private static final Logger log = Logger.getLogger(PushDeployer.class.getName());
    private final Cluster cluster;

    public PushDeployer(Cluster cluster) { this.cluster = cluster; }

    // kubectl apply from Jenkins: no Git source of truth, no drift detection.
    public void deploy(String tag) {
        log.info(() -> "Jenkins kubectl apply -> " + tag + " (no drift tracking)");
        cluster.apply(tag);
    }
}
