package com.bank.gitops;

import java.util.logging.*;

public class GitOpsDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new GitOpsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(GitOpsDemo.class.getName());

        GitRepo git = new GitRepo("transfer-service:1.0.0");
        Cluster cluster = new Cluster("transfer-service:1.0.0");
        GitOpsController controller = new GitOpsController(git, cluster, true);

        log.info("=== Deploy via Git commit ===");
        git.commit("transfer-service:1.1.0"); // CI proposes new desired state
        controller.reconcile();                // controller pulls + applies

        log.info("=== Drift: someone runs manual kubectl ===");
        cluster.manualOverride("transfer-service:hotfix-manual");
        controller.reconcile();                // self-heal reverts drift

        log.info("=== Rollback via git revert ===");
        git.revert();                          // back to 1.0.0
        controller.reconcile();                // controller rolls cluster back

        log.info("=== Contrast: old push-based Jenkins deploy ===");
        new PushDeployer(cluster).deploy("transfer-service:1.2.0-untracked");
        controller.reconcile();                // controller heals it back to Git!
    }
}

// ─── Would be in GitOpsLogFormatter.java in a real project ───
class GitOpsLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
